import { useState } from 'react';
import type { FormEvent } from 'react';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { GRADES } from '../people/people';
import { twoDecimals } from '../rates/rates';
import { useGradeDue, useSheetExists } from './sheetcompare';

// The other sheet's figures, read only once it is known to exist (reading a sheet makes it exist).
function OtherLines({ sheet, other }: { sheet: string; other: string }) {
  const mine = useGradeDue(sheet);
  const theirs = useGradeDue(other);
  if (!mine.ready || !theirs.ready) return null;
  return (
    <>
      {GRADES.map((g) => (
        <div key={g} data-testid="compare-line">
          {`${g} ${twoDecimals(mine.due[g])} ${twoDecimals(theirs.due[g])}`}
        </div>
      ))}
    </>
  );
}

function Comparison({ sheet, other }: { sheet: string; other: string }) {
  const exists = useSheetExists(other);
  if (!exists.isSuccess || exists.isFetching || !exists.data) return null;
  return <OtherLines sheet={sheet} other={other} />;
}

// Compares this sheet with another by id: one line per grade of this sheet, its summary due-total for the grade then
// the other sheet's (0.00 for a grade the other sheet has no one on). A sheet that does not exist gives no lines.
function SheetCompare({ sheet }: { sheet: string; user: string }) {
  const [entry, setEntry] = useState('');
  // Each press remounts the comparison, so the old lines go and every figure is read afresh.
  const [asked, setAsked] = useState<{ other: string; n: number } | null>(null);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setAsked((prev) => ({ other: entry.trim(), n: (prev?.n ?? 0) + 1 }));
  };

  return (
    <form onSubmit={submit}>
      Compare with sheet:{' '}
      <input data-testid="compare-sheet" type="text" placeholder="sheet id" value={entry}
        onChange={(e) => setEntry(e.target.value)} />{' '}
      <button type="submit" data-testid="compare">
        Compare
      </button>
      {asked && asked.other !== '' && <Comparison key={asked.n} sheet={sheet} other={asked.other} />}
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 86, Component: SheetCompare });
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { GRADES, isRetired, usePeople } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import { hundredths, twoDecimals, useRates } from '../rates/rates';
import { useFloorCents, useReviewSla } from '../settings/settings';
import { CLAIM_STATUSES, isActive, personDueCents, reviewLate, statusCount, useClaims, useLate } from '../claims/claims';
import { useVoidReasons } from '../voidreasons/voidreasons';
import { classicPeriodDueCents, periodDueCents, shownDueTotal, usePeriods } from '../periods/periods';
import { Fig } from '../locale/Fig';
import { useCapCentsOf } from '../pools/pools';

// The sheet at a glance, figured exactly as the lists figure it. Per grade: the people on it today (retired ones
// excluded), their due-totals added up (an n/a due-total adds nothing) and how many of them are active. Per period: its due-total, as its row shows
// it, and its change from the period before it by from-date (none for the earliest). Per status: how many of the sheet's claims have it (every claim, whoever's). Per void reason on the list: how
// many VOID claims were voided with it. And how many REVIEW claims are late for review.
// Beside it, the classic summary: per period, its due-total counting each claim by its status now (a closed period shows
// the figure fixed when it closed), and the sheet's due-total untrimmed (everyone's due-total added up, n/a adding nothing).
function Summary({ sheet }: { sheet: string; user: string }) {
  const { data: claims = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: periods = [] } = usePeriods(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloorCents(sheet);
  const capOf = useCapCentsOf(sheet);
  const late = useLate(sheet);
  const reviewSla = useReviewSla(sheet);
  const { data: voidReasons = [] } = useVoidReasons(sheet);

  const current = people.filter((p) => !isRetired(p));
  const periodTotals = periodDueCents(periods, claims, people, rates, floor, late);
  const shownTotals = [...periods]
    .sort((a, b) => a.from.localeCompare(b.from))
    .map((p) => ({ period: p, shown: shownDueTotal(p, periodTotals.get(p.name) ?? 0n) }));
  const classicTotals = classicPeriodDueCents(periods, claims, people, rates, floor, late);
  const classicDue = people.reduce((sum, p) => sum + (personDueCents(claims, rates, p, today, floor, late, capOf(p), people) ?? 0n), 0n);
  const periodChanges = new Map(
    shownTotals.map(({ period, shown }, i) => [
      period.name,
      i === 0 ? '' : twoDecimals(hundredths(shown) - hundredths(shownTotals[i - 1].shown)),
    ]),
  );

  return (
    <section>
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = current.filter((p) => p.grade === g);
            const due = onGrade.reduce((sum, p) => sum + (personDueCents(claims, rates, p, today, floor, late, capOf(p), people) ?? 0n), 0n);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}><Fig>{twoDecimals(due)}</Fig></td>
                <td data-testid={`summary-grade-${g}-active`}>{onGrade.filter((p) => isActive(claims, p, today)).length}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}><Fig>{shownDueTotal(p, periodTotals.get(p.name) ?? 0n)}</Fig></td>
              <td data-testid={`summary-period-${p.name}-change`}><Fig>{periodChanges.get(p.name)}</Fig></td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {CLAIM_STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{statusCount(claims, s)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p>
        Late for review: <strong data-testid="summary-review-late-count">{claims.filter((c) => reviewLate(c, reviewSla, today)).length}</strong>
      </p>
      <h3>Classic summary</h3>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`classic-period-${p.name}-due-total`}><Fig>{shownDueTotal(p, classicTotals.get(p.name) ?? 0n)}</Fig></td>
            </tr>
          ))}
        </tbody>
      </table>
      <p>
        Due total: <strong data-testid="classic-due-total"><Fig>{twoDecimals(classicDue)}</Fig></strong>
      </p>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map((r) => (
            <tr key={r.reason}>
              <td>{r.reason}</td>
              <td data-testid={`summary-void-${r.reason}-count`}>{r.voided}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 30, Component: Summary });
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { GRADES } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import type { Grade } from '../people/people';
import { rateOf, ratePreviewPath, ratesKey, ratesPath, useRates } from './rates';
import type { Rate, RatePreview } from './rates';
import { Fig } from '../locale/Fig';

type Draft = { grade: Grade; pct: string; from: string; to: string };
const EMPTY: Draft = { grade: 'A', pct: '', from: '', to: '' };

// The sheet's rates: each grade's rate in force on the sheet's today (n/a when none), a calendar of each grade's rate
// on the first day of each month of today's calendar year (n/a when none), every rate with its
// from-date (a blank from-date applies from the start) and to-date (a blank one has no end), and a form that sets one, replacing the rate already
// there for that grade and from-date as a new version (each row shows its version count; the newest is in force).
function Rates({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const [draft, setDraft] = useState<Draft>(EMPTY);
  // The rate calendar: each month (yyyy-MM) of the sheet's today's calendar year, read on its first day.
  const year = today?.slice(0, 4);
  const months = year ? Array.from({ length: 12 }, (_, i) => `${year}-${String(i + 1).padStart(2, '0')}`) : [];

  const save = useMutation({
    mutationFn: (body: Draft) => postJson<Rate[]>(byUser(ratesPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(ratesKey(sheet), updated);
      setDraft((d) => ({ ...d, pct: '', from: '', to: '' }));
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a percent that is not 0.00 or more with up to two decimals, a bad from- or to-date, or a to-date before the from-date.
    send(draft);
  };

  // The preview of a candidate rate: read-only, it saves nothing and audits nothing.
  const [previewGrade, setPreviewGrade] = useState<Grade>('A');
  const [previewPct, setPreviewPct] = useState('');
  const preview = useMutation({
    mutationFn: ({ grade, pct }: { grade: Grade; pct: string }) =>
      getJson<RatePreview>(ratePreviewPath(sheet, grade, pct)),
  });
  const runPreview = () => {
    preview.reset();
    preview.mutate({ grade: previewGrade, pct: previewPct });
  };

  return (
    <section>
      <h2>Rates</h2>
      <form onSubmit={submit}>
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={draft.grade}
            onChange={(e) => change({ grade: e.target.value as Grade })}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input data-testid="rate-form-pct" value={draft.pct} onChange={(e) => change({ pct: e.target.value })} />
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="rate-form-from"
            placeholder="yyyy-mm-dd (blank: from the start)"
            value={draft.from}
            onChange={(e) => change({ from: e.target.value })}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            data-testid="rate-form-to"
            placeholder="yyyy-mm-dd (blank: no end)"
            value={draft.to}
            onChange={(e) => change({ to: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && (
          <span data-testid="rate-form-error" role="alert">
            {' '}A rate needs a grade of A, B or C and a percent of 0.00 or more with up to two decimals, a from-date and a to-date that are each a valid date or blank, and a to-date not before the from-date.
          </span>
        )}
      </form>
      <div>
        <label>
          Preview grade{' '}
          <select
            data-testid="rate-preview-grade"
            value={previewGrade}
            onChange={(e) => {
              setPreviewGrade(e.target.value as Grade);
              preview.reset();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Candidate rate %{' '}
          <input
            data-testid="rate-preview-pct"
            value={previewPct}
            onChange={(e) => {
              setPreviewPct(e.target.value);
              preview.reset();
            }}
          />
        </label>{' '}
        <button type="button" data-testid="rate-preview" disabled={preview.isPending} onClick={runPreview}>
          Preview
        </button>
        {preview.data && (
          <span>
            {' '}Claims changed: <span data-testid="rate-preview-count">{preview.data.count}</span>, difference:{' '}
            <span data-testid="rate-preview-diff"><Fig>{preview.data.diff}</Fig></span>
          </span>
        )}
        {preview.isError && (
          <span data-testid="rate-preview-error" role="alert">
            {' '}A preview needs a grade of A, B or C and a percent of 0.00 or more with up to two decimals.
          </span>
        )}
      </div>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}><Fig>{rateOf(rates, g, today) ?? 'n/a'}</Fig></td>
            </tr>
          ))}
        </tbody>
      </table>
      {months.length > 0 && (
        <table>
          <thead>
            <tr>
              <th>Grade</th>
              {months.map((m) => (
                <th key={m}>{m}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {GRADES.map((g) => (
              <tr key={g}>
                <td>{g}</td>
                {months.map((m) => (
                  <td key={m} data-testid={`rate-month-${g}-${m}`}><Fig>{rateOf(rates, g, `${m}-01`) ?? 'n/a'}</Fig></td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      )}
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>To</th>
            <th>Rate %</th>
            <th>Versions</th>
          </tr>
        </thead>
        <tbody>
          {rates.filter((r) => (r.level ?? 0) === 0).map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? 'start'}</td>
              <td data-testid="rate-to">{r.to ?? ''}</td>
              <td>
                <span data-testid="rate-pct"><Fig>{r.pct}</Fig></span>
              </td>
              <td data-testid="rate-version">{r.version ?? 1}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

